import React, { Component } from 'react';
// import axios from 'axios';

class UseWeather extends Component {
    constructor(props) {
        super(props);
        const weatherData = {
            results: null,
            loading: false,
            error: null,
            hourlyResults: null,
            iconResponse: [],
        };
    }

    fetchWeather = async (input) => {
        // this.setState({ loading: true, error: null });
        try {
            // Fetch current weather data
            const response1 = await axios.get(`https://api.openweathermap.org/data/2.5/weather?q=${input}&APPID=caf423eea1b73c5d7b4b04ceb8e98b3a`);
            this.setState({ results: response1.data }); // Set results from the response

            const hourlyData = await axios.get(`https://weather.visualcrossing.com/VisualCrossingWebServices/rest/services/timeline/${input}?unitGroup=us&key=M4KYF73YL3J4KA6CTWWEC2U7P&contentType=json`);
            this.setState({ hourlyResults: hourlyData.data }); // Set hourly results

            // Uncomment if you want to fetch the icon
            // let iconId = response1.data.weather[0].icon;
            // const response3 = await axios.get(`https://openweathermap.org/img/wn/${iconId}@2x.png`);
            // this.setState({ iconResponse: response3.data.imageUrl });
        } catch (err) {
            this.setState({ error: err.message }); // Set error message from the caught error
        } finally {
            this.setState({ loading: false }); // Set loading to false after the request is complete
        }
    };

    render() {
        // This component does not render anything by itself
        return null; // You can return null or any other JSX if needed
    }
}

export default UseWeather;
